        service.confirm(invoiceStay.id());
        assertEquals("""
                Fatura de hospedagem nº 1
                Empresa: Tecnosul Ltda (CNPJ 12.345.678/0001-90)
                Hóspede: Ana Souza
                Quarto: 201 (DELUXE)
                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
                Diárias: R\$ 779,80
                Total: R\$ 779,80
                ISS retido (5%): R\$ 38,99
                """, service.receiptCopy(invoiceStay.id()).text());

        Guest foreigner = new Guest("John Smith", "john\@example.com",
                new Identification.Passport("X1234567", "United Kingdom"));
        Reservation foreignStay = service.create(new NewReservation(
                301, foreigner, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-11"), 1,
                RatePlan.NON_REFUNDABLE));
        service.confirm(foreignStay.id());
        assertEquals("""
                Booking receipt no. 2
                Guest: John Smith (passport X1234567, United Kingdom)
                Room: 301 (SUITE)
                Check-in: 2027-03-10 | Check-out: 2027-03-11 | 1 night
                Nights: BRL 579.90
                Discount: BRL 86.99
                Total: BRL 492.91
                """, service.receiptCopy(foreignStay.id()).text());
        ReservationReceipt receipt = service.receiptCopy(foreignStay.id());
        assertNull(receipt.guestCpf());
        assertNull(receipt.companyCnpj());
        assertEquals("United Kingdom", receipt.guestCountry());
        assertTrue(sentMessages.all().get(1).body().contains("Booking receipt no. 2"));
    }

