        String cpf = "\"guestCpf\": \"111.222.333-44\",";
        String half = "\"companyCnpj\": \"12.345.678/0001-90\",";

        assertEquals(400, post("/reservations", base).statusCode());
        assertEquals(400, post("/reservations", base.replace("{", "{" + cpf + company)).statusCode());
        assertEquals(400, post("/reservations", base.replace("{", "{" + company + passport)).statusCode());
        assertEquals(400, post("/reservations", base.replace("{", "{" + half)).statusCode());

        HttpResponse<String> created = post("/reservations", base.replace("{", "{" + company));
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        assertEquals("Tecnosul Ltda", reservation.get("companyName").asText());
        assertTrue(reservation.get("guestCpf").isNull());
        assertTrue(reservation.get("guestPassport").isNull());

        long id = reservation.get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");
        JsonNode document = json.readTree(get("/reservations/" + id + "/document").body());
        assertEquals("Fatura de hospedagem", document.get("title").asText());
        assertTrue(document.get("guestCpf").isNull());
        assertEquals("12.345.678/0001-90", document.get("companyCnpj").asText());
        assertTrue(document.get("text").asText().contains("ISS retido (5%): R\$ 46,79"));

        HttpResponse<String> foreign = post("/reservations", base.replace("{", "{" + passport).replace("2027-07-1", "2027-08-1"));
